(677, 'vi', 1, 'encryptedcode', 'Encrypted code', 'Mã đã mã hoá', NULL, 1780544377, NULL, 0, 0),
(678, 'vi', 1, 'enddate', 'Course end date', 'Ngày kết thúc khóa học', NULL, 1780544377, NULL, 0, 0),
(679, 'vi', 1, 'enddate_help', 'The end date doesn’t restrict student access to the course. It determines whether a course is listed as Past in My courses.', 'Ngày kết thúc khóa được sử dụng để xác định xem một khóa học có được thêm vào danh sách khóa học của người sử dụng. Khi ngày kết thúc khóa học kết thúc, khóa học sẽ không còn được liệt kê trong bảng định hướng và nó sẽ ở trong danh sách các khóa học cũ. Ngày kết thúc khóa cũng có thể được sử dụng trong báo cáo đặc thù. Người sử dụng có thể đăng nhập vào khóa học sau ngày kết thúc, nói cách khác, ngày không giới hạn việc đăng nhập.', NULL, 1780544377, NULL, 0, 0),
(680, 'vi', 1, 'enddatewithtaskenabled', 'Course end date', 'Course end date', NULL, 1780544377, NULL, 0, 0),
(681, 'vi', 1, 'enddatewithtaskenabled_help', 'The date when the course becomes hidden for students and they can no longer access it.', 'The date when the course becomes hidden for students and they can no longer access it.', NULL, 1780544377, NULL, 0, 0),
(682, 'vi', 1, 'english', 'English', 'Tiếng Anh', NULL, 1780544377, NULL, 0, 0),
(683, 'vi', 1, 'enrolmentmethods', 'Enrolment methods', 'Phương thức đăng ký', NULL, 1780544377, NULL, 0, 0),
(684, 'vi', 1, 'entercourse', 'Click to enter this course', 'Nhấn vào đây để truy cập khoá học', NULL, 1780544377, NULL, 0, 0),
(685, 'vi', 1, 'enteremail', 'Enter your email address', 'Nhập thư điện của bạn vào', NULL, 1780544377, NULL, 0, 0),
(686, 'vi', 1, 'enteremailaddress', 'Enter in your email address to reset your\n   password and have the new password sent to you via email.', 'Cho biết địa chỉ điện thư để đổi mật khẩu và nhận thư thông báo mật khẩu mới.', NULL, 1780544377, NULL, 0, 0),
