(690, 'vi', 1, 'errorcreatingactivity', 'Unable to create an instance of activity \'{$a}\'', 'Không thể tạo một phiên bản của hoạt động \'{$a}\'', NULL, 1780544377, NULL, 0, 0),
(691, 'vi', 1, 'errorfiletoobig', 'The file was bigger than the limit of {$a} bytes', 'Tập tin lớn hơn giới hạn {$a} bytes', NULL, 1780544377, NULL, 0, 0),
(692, 'vi', 1, 'errornouploadrepo', 'There is no upload repository enabled for this site', 'Kho tải tập tin không được kích hoạt ở hệ thống này', NULL, 1780544377, NULL, 0, 0),
(693, 'vi', 1, 'errorwhenconfirming', 'You are not confirmed yet because an error occurred.  If you clicked on a link in an email to get here, make sure that the line in your email wasn\'t broken or wrapped. You may have to use cut and paste to reconstruct the link properly.', 'Đã có lỗi xảy ra nên tài khoản của bạn chưa được xác nhận. Nếu bạn truy cập vào đây bằng cách nhấn lên đường liên kết trong điện thư, hãy kiểm tra lại xem liên kết này có bị đứt đoạn hay không. Nếu là bị đứt đoạn, bạn cần phải dùng các thao tác cắt và dán để có được địa chỉ chính xác.', NULL, 1780544377, NULL, 0, 0),
(694, 'vi', 1, 'eventcommentcreated', 'Comment created', 'Lời bình đã được tạo', NULL, 1780544377, NULL, 0, 0),
