(970, 'vi', 1, 'filtertype', 'Filter type', 'Kiểu lọc', NULL, 1780544378, NULL, 0, 0),
(971, 'vi', 1, 'icon', 'Icon', 'Biểu tượng', NULL, 1780544378, NULL, 0, 0),
(972, 'vi', 1, 'idnumber', 'ID number', 'Mã số ID', NULL, 1780544378, NULL, 0, 0),
(973, 'vi', 1, 'idnumbercourse', 'Course ID number', 'Mã số ID khoá học', NULL, 1780544378, NULL, 0, 0),
(974, 'vi', 1, 'idnumbercourse_help', 'Only used to connect the course with external systems. Leave blank if you don\'t have an official course ID.', 'Số ID của một cua học chỉ được sử dụng khi khớp cua học này với các hệ thống ở ngoài - nó không bao giờ được hiển thị trong Moodle.  Nếu bạn có tên mã chính thức cho cua học này thi sử dụng nó tại đây ... nếu không bạn có thể để nó trống.', NULL, 1780544378, NULL, 0, 0),
(975, 'vi', 1, 'idnumbergroup', 'Group ID number', 'Số ID nhóm', NULL, 1780544378, NULL, 0, 0),
(976, 'vi', 1, 'idnumbergroup_help', 'The ID number of a group is only used when matching the group against external systems and is not displayed anywhere on the site. If the group has an official code name it may be entered, otherwise the field can be left blank.', 'Số ID của một nhóm chỉ được sử dụng khi nhóm lại với hệ thống bên ngoài và không được hiển thị ở bất cứ đâu trên trang. Nếu nhóm có mã tên chính thức có thể nhập vào, ngược lại có thể để trống mục này.', NULL, 1780544378, NULL, 0, 0),
(977, 'vi', 1, 'idnumbergrouping', 'Grouping ID number', 'Số ID nhóm', NULL, 1780544378, NULL, 0, 0);
INSERT INTO `mdl_tool_customlang` (`id`, `lang`, `componentid`, `stringid`, `original`, `master`, `local`, `timemodified`, `timecustomized`, `outdated`, `modified`) VALUES
(978, 'vi', 1, 'idnumbergrouping_help', 'The ID number of a grouping is only used when matching the grouping against external systems and is not displayed anywhere on the site. If the grouping has an official code name it may be entered, otherwise the field can be left blank.', 'Số ID của một nhóm chỉ được sử dụng khi nhóm lại với hệ thống bên ngoài và không được hiển thị ở bất cứ đâu trên trang. Nếu nhóm có mã tên chính thức có thể nhập vào, ngược lại có thể để trống mục này.', NULL, 1780544378, NULL, 0, 0),
(979, 'vi', 1, 'idnumbermod', 'ID number', 'Mã số ID', NULL, 1780544378, NULL, 0, 0),
(980, 'vi', 1, 'idnumbermod_help', 'Setting an ID number provides a way of identifying the activity or resource for purposes such as grade calculation or custom reporting. Otherwise the field may be left blank.\n\nFor gradable activities, the ID number can also be set in the gradebook, though it can only be edited on the activity settings page.', 'Thiết lập một Số ID sẽ cung cấp một cách thức để xác định hoạt động nhằm mục đích tính toán điểm số. nếu hoạt động không liên quan đến việc tính toán điểm số thì Số ID có thể để trống.\n\nSố ID có thể được đặt ở số điểm, cho dù nó chỉ có thể được chỉnh sửa ở trang thiết lập hoạt động.', NULL, 1780544378, NULL, 0, 0),
(981, 'vi', 1, 'idnumbertaken', 'This ID number is already taken', 'Mã số ID này đã được sử dụng rồi', NULL, 1780544378, NULL, 0, 0),
(982, 'vi', 1, 'imagealt', 'Picture description', 'Mô tả hình ảnh', NULL, 1780544378, NULL, 0, 0),
(983, 'vi', 1, 'import', 'Import', 'Nhập dữ liệu', NULL, 1780544378, NULL, 0, 0),
(984, 'vi', 1, 'importdata', 'Import course data', 'Nhập dữ liệu của khoá học', NULL, 1780544378, NULL, 0, 0),
(985, 'vi', 1, 'importdataexported', 'Exported data from \'from\' course successfully.<br /> Continue to import into your \'to\' course.', 'Đã xuất thành công dữ liệu từ khoá học nguồn.<br />Bạn có muốn tiếp tục nhập dữ liệu vào khoá học đích?', NULL, 1780544378, NULL, 0, 0),
(986, 'vi', 1, 'importdatafinished', 'Import complete! Continue to your course', 'Đã nhập xong dữ liệu. Bạn có thể đi tiếp vào khoá học của mình.', NULL, 1780544378, NULL, 0, 0),
(987, 'vi', 1, 'importdatafrom', 'Find a course to import data from:', 'Tìm khoá học chứa dữ liệu nguồn', NULL, 1780544378, NULL, 0, 0),
(988, 'vi', 1, 'importinfo', 'Import items from other courses, such as activities, blocks or calendar events. No user data will be imported.', 'Import items from other courses, such as activities, blocks or calendar events. No user data will be imported.', NULL, 1780544378, NULL, 0, 0),
(989, 'vi', 1, 'inactive', 'Inactive', 'Không hoạt động', NULL, 1780544378, NULL, 0, 0);
